def reverseVowels(s):
    vowels = set('aeiouAEIOU')
    extracted = [c for c in s if c in vowels]
    res = []
    for c in s:
        if c in vowels:
            res.append(extracted.pop())
        else:
            res.append(c)
    return ''.join(res)

